theme.css:
#wemd{color:#111111;background-color:#fdfdfb;font-family:'Source Han Serif SC', 'Noto Serif SC', Georgia, serif;font-size:16px;line-height:1.85;letter-spacing:0.01em;text-align:justify;padding:36px 28px;overflow-wrap:anywhere}
#wemd p{margin:0 0 1.3em;text-indent:2em}
#wemd h1{font-size:30px;font-weight:900;color:$colors.text_primary;margin-top:2em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid $colors.text_primary;padding-bottom:.4em}
#wemd h2{font-size:22px;font-weight:700;color:$colors.text_primary;margin-top:1.8em;margin-bottom:0.8em;text-align:left;border-bottom:1px solid $colors.border;padding-bottom:.4em}
#wemd h3{font-size:18px;font-weight:700;color:$colors.text_primary;margin-top:1.5em;margin-bottom:0.6em}
#wemd h4{font-size:16px;font-weight:600;color:$colors.text_secondary;margin-top:1.2em;margin-bottom:0.5em}
#wemd blockquote{border-left:5px solid $colors.quote_border;background:$colors.quote_background;padding:14px 22px;color:$colors.text_secondary;font-style:italic;margin:1.2em 0}
#wemd code{background-color:$colors.code_background;color:#991b1b;padding:1px 5px;border-radius:2px;font-size:0.9em;font-family:'Courier New', monospace}
#wemd pre{background:$colors.code_background;border-radius:2px;padding:14px 18px;line-height:1.5;white-space:pre-wrap}
#wemd pre code{background:transparent;padding:0}
#wemd table{width:100%;border-collapse:collapse}
#wemd th, #wemd td{border:1px solid $colors.border;padding:8px 12px}
#wemd th{background:$colors.table_header_bg}
#wemd tr:nth-child(even){background:$colors.table_stripe_bg}
#wemd ul, #wemd ol{padding-left:24px;margin:1em 0}
#wemd ul{list-style-type:square}
#wemd ol{list-style-type:decimal}
#wemd li{margin-bottom:6px}
#wemd li::marker{color:$colors.text_primary}
#wemd hr{border:0;border-top:1px solid $colors.text_primary;margin:2em 0;width:100%}
#wemd img{max-width:100%;height:auto;border-radius:2px}
#wemd figcaption{font-size:13px;color:$colors.text_secondary;text-align:left}
#wemd a{color:$colors.link_color;text-decoration:underline}
#wemd strong{color:#111111;font-weight:700}
#wemd mark{background:$colors.highlight_bg;padding:1px 4px;border-radius:0px}
#wemd > p:first-of-type::first-letter{float:left;font-size:3.5em;color:$colors.text_primary;line-height:1.1;margin-right:.12em}
